DROP TABLE IF EXISTS `CMSPage`;
CREATE TABLE `CMSPage` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `excerpt` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('DRAFT','PUBLISHED','ARCHIVED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `published` tinyint(1) NOT NULL DEFAULT '0',
  `publishedAt` datetime(3) DEFAULT NULL,
  `authorId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `updatedAt` datetime(3) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `CMSPage_slug_key` (`slug`),
  KEY `CMSPage_status_idx` (`status`),
  KEY `CMSPage_published_idx` (`published`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `CMSPage` (`id`, `slug`, `title`, `excerpt`, `content`, `status`, `published`, `publishedAt`, `authorId`, `metadata`, `updatedAt`, `createdAt`) VALUES ('page-37e56c5496bce693171c7f7ef6276187', 'nin-centre', 'HambakTech NIN & Identity Facilitation Centre', NULL, 'Authorized collation and validation desk for National Identification Number (NIN) modifications, standard and premium slip reprints, tracking reference lookups, and BVN validation services with strict NDPR data protection.', 'PUBLISHED', '0', NULL, NULL, NULL, '2026-10-08 03:13:06.369', '2026-10-08 03:13:06.369');
INSERT INTO `CMSPage` (`id`, `slug`, `title`, `excerpt`, `content`, `status`, `published`, `publishedAt`, `authorId`, `metadata`, `updatedAt`, `createdAt`) VALUES ('page-8d8ad153421e3a3754579d2eafee2adc', 'how-it-works', 'How HambakTech Works', NULL, '1. Choose your desired digital, academy, or identity service. 2. Fund your dedicated digital wallet via direct bank transfer to Moniepoint MFB. 3. Track real-time progress and receive instant delivery directly to your dashboard.', 'PUBLISHED', '0', NULL, NULL, NULL, '2026-10-08 03:13:06.302', '2026-10-08 03:13:06.302');
INSERT INTO `CMSPage` (`id`, `slug`, `title`, `excerpt`, `content`, `status`, `published`, `publishedAt`, `authorId`, `metadata`, `updatedAt`, `createdAt`) VALUES ('page-d12e2d74fb1e4b17832f00fea271fb5f', 'about-us', 'About Hambak Tech & Services', NULL, 'Hambak Tech & Services is a registered ICT firm delivering next-generation digital engineering, enterprise identity collation desks, and technical vocational academy cohorts. Registered under the Corporate Affairs Commission (BN 9284726).', 'PUBLISHED', '0', NULL, NULL, NULL, '2026-10-08 03:13:06.232', '2026-10-08 03:10:45.345');

DROP TABLE IF EXISTS `Cohort`;
CREATE TABLE `Cohort` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `courseId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `startDate` datetime(3) NOT NULL,
  `endDate` datetime(3) NOT NULL,
  `capacity` int NOT NULL DEFAULT '30',
  `status` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'upcoming',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `Cohort_courseId_idx` (`courseId`),
  CONSTRAINT `Cohort_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `Course` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `CommunicationDelivery`;
CREATE TABLE `CommunicationDelivery` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `notificationId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `channel` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `recipientAddress` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerMessageId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `failureReason` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attemptedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deliveredAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `CommunicationDelivery_notificationId_idx` (`notificationId`),
  KEY `CommunicationDelivery_channel_idx` (`channel`),
  KEY `CommunicationDelivery_status_idx` (`status`),
  KEY `CommunicationDelivery_createdAt_idx` (`createdAt`),
  CONSTRAINT `CommunicationDelivery_notificationId_fkey` FOREIGN KEY (`notificationId`) REFERENCES `Notification` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

