DROP TABLE IF EXISTS `CustomerProfile`;
CREATE TABLE `CustomerProfile` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `state` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lga` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ninNumberEncrypted` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bvnNumberEncrypted` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idType` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dateOfBirth` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isIdentityVerified` tinyint(1) NOT NULL DEFAULT '0',
  `kycStatus` enum('NOT_SUBMITTED','PENDING','IN_REVIEW','VERIFIED','REJECTED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_SUBMITTED',
  `kycSubmittedAt` datetime(3) DEFAULT NULL,
  `kycVerifiedAt` datetime(3) DEFAULT NULL,
  `kycRejectionReason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `tier` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tier_1',
  `dailyTransactionLimitKobo` bigint NOT NULL DEFAULT '5000000',
  `transactionPinHash` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pinFailedAttempts` int NOT NULL DEFAULT '0',
  `pinLockedUntil` datetime(3) DEFAULT NULL,
  `pinSetAt` datetime(3) DEFAULT NULL,
  `pinResetTokenHash` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pinResetExpiresAt` datetime(3) DEFAULT NULL,
  `termsAcceptedVersion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `termsAcceptedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `CustomerProfile_userId_key` (`userId`),
  KEY `idx_cp_kyc_status` (`kycStatus`),
  CONSTRAINT `CustomerProfile_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

