DROP TABLE IF EXISTS `DashboardConfig`;
CREATE TABLE `DashboardConfig` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dashboardType` enum('CUSTOMER','STUDENT','ADMIN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `welcomeHeading` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `welcomeSubheading` text COLLATE utf8mb4_unicode_ci,
  `isBannerEnabled` tinyint(1) NOT NULL DEFAULT '0',
  `bannerText` text COLLATE utf8mb4_unicode_ci,
  `bannerType` enum('INFO','WARNING','SUCCESS','CRITICAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INFO',
  `supportHeadline` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Dedicated Customer Help Desk',
  `supportText` text COLLATE utf8mb4_unicode_ci,
  `supportPhone` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supportEmail` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supportWhatsapp` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emptyOrdersMessage` text COLLATE utf8mb4_unicode_ci,
  `emptyTransactionsMessage` text COLLATE utf8mb4_unicode_ci,
  `emptyCoursesMessage` text COLLATE utf8mb4_unicode_ci,
  `emptyTicketsMessage` text COLLATE utf8mb4_unicode_ci,
