  UNIQUE KEY `uniq_type_widget_key` (`dashboardType`,`widgetKey`),
  KEY `idx_dw_order` (`dashboardType`,`displayOrder`),
  KEY `idx_dw_enabled` (`isEnabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

