INSERT INTO `EmailTemplate` (`id`, `code`, `name`, `subject`, `bodyHtml`, `bodyText`, `availableVariables`, `isActive`, `updatedAt`, `createdAt`) VALUES ('tpl-general-announcement', 'GENERAL_ANNOUNCEMENT', 'General Platform Announcement', 'HambakTech Update: {{headline}}', '<!DOCTYPE html>
