<div style=\"font-size: 14px; color: #334155; line-height: 1.65; margin: 20px 0;\">{{message}}</div>
        </div>
        <div style=\"text-align: center; margin: 28px 0 20px 0;\"><a href=\"{{actionUrl}}\" style=\"display: inline-block; background-color: #2563eb; color: #ffffff !important; font-size: 14px; font-weight: 700; text-decoration: none; padding: 13px 32px; border-radius: 10px; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\" target=\"_blank\" rel=\"noopener noreferrer\">{{actionText}}</a></div>
        
