INSERT INTO `EmailTemplate` (`id`, `code`, `name`, `subject`, `bodyHtml`, `bodyText`, `availableVariables`, `isActive`, `updatedAt`, `createdAt`) VALUES ('tpl-order-failed', 'ORDER_FAILED', 'Order Failed Notice', 'Notice: Action Required on Order #{{orderNumber}}', '<!DOCTYPE html>
