    .body-copy { font-size: 14px; color: #334155; line-height: 1.65; }
    .detail-card { background-color: #f8fafc; border: 1px solid #e2e8f0; border-left: 4px solid #dc2626; border-radius: 10px; padding: 18px 20px; margin: 20px 0; font-size: 13px; line-height: 1.6; color: #334155; }
    .btn-container { text-align: center; margin: 28px 0; }
    .action-btn { display: inline-block; background-color: #dc2626; color: #ffffff !important; font-size: 14px; font-weight: 700; text-decoration: none; padding: 13px 32px; border-radius: 10px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1); }
    .email-footer { background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 24px 28px; text-align: center; font-size: 12px; color: #64748b; }
    .footer-links a { color: #2563eb; text-decoration: none; font-weight: 600; margin: 0 8px; }
