INSERT INTO `EmailTemplate` (`id`, `code`, `name`, `subject`, `bodyHtml`, `bodyText`, `availableVariables`, `isActive`, `updatedAt`, `createdAt`) VALUES ('tpl-security-alert', 'SECURITY_ALERT', 'Security Alert', 'SECURITY ALERT: Urgent Activity on Your HambakTech Account', '<!DOCTYPE html>
<html lang=\"en\">
