DROP TABLE IF EXISTS `Enrollment`;
CREATE TABLE `Enrollment` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `courseId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `cohortId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `studentId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `enrolledAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `progressPercent` int NOT NULL DEFAULT '0',
  `isCompleted` tinyint(1) NOT NULL DEFAULT '0',
  `completedAt` datetime(3) DEFAULT NULL,
  `studentIdNumber` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `internalQrCode` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Enrollment_studentIdNumber_key` (`studentIdNumber`),
  KEY `Enrollment_userId_idx` (`userId`),
  KEY `Enrollment_courseId_idx` (`courseId`),
  KEY `Enrollment_enrolledAt_idx` (`enrolledAt`),
  KEY `Enrollment_cohortId_fkey` (`cohortId`),
  KEY `Enrollment_studentId_fkey` (`studentId`),
  CONSTRAINT `Enrollment_cohortId_fkey` FOREIGN KEY (`cohortId`) REFERENCES `Cohort` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Enrollment_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `Course` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `Enrollment_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `Student` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Enrollment_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `Enrollment` (`id`, `userId`, `courseId`, `cohortId`, `studentId`, `enrolledAt`, `progressPercent`, `isCompleted`, `completedAt`, `studentIdNumber`, `internalQrCode`) VALUES ('enr-4a18bc82febdaa39029f8acfb5599322', 'usr-2581daa91cc85efbe0256802c08b51ec', 'course-basic-ict', NULL, 'stu-edbb4b4eac960ff1cd4a92d4e14732c0', '2026-11-05 19:16:52.815', '0', '0', NULL, 'HAM-STU-2026-272FA', 'QR-HAM-2026-26dda875');

DROP TABLE IF EXISTS `FAQ`;
CREATE TABLE `FAQ` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `question` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `order` int NOT NULL DEFAULT '0',
  `status` enum('DRAFT','PUBLISHED','ARCHIVED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `publishedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `isPublished` tinyint(1) NOT NULL DEFAULT '1',
  `displayOrder` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `FAQ_category_idx` (`category`),
  KEY `FAQ_status_idx` (`status`),
  KEY `FAQ_order_idx` (`order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `FAQ` (`id`, `category`, `question`, `answer`, `order`, `status`, `publishedAt`, `createdAt`, `updatedAt`, `isPublished`, `displayOrder`) VALUES ('faq-5da281bcce90870ff30ed3cae2546c92', 'WALLET', 'How do I fund my HambakTech digital wallet?', 'You can top up your wallet instantly using your personalized Dedicated Virtual Bank Account (Sterling/Wema/Moniepoint), Debit Card via Paystack, or direct Bank Transfer to Moniepoint MFB.', '0', 'DRAFT', NULL, '2026-10-08 03:13:06.773', '2026-10-08 03:13:06.773', '1', '2');
INSERT INTO `FAQ` (`id`, `category`, `question`, `answer`, `order`, `status`, `publishedAt`, `createdAt`, `updatedAt`, `isPublished`, `displayOrder`) VALUES ('faq-5ffa7c58533dfa0d591b4df6819daa14', 'Support', 'What is the official customer support response time?', 'Our customer facilitation desk responds within 5 to 15 minutes during standard operational hours.', '0', 'DRAFT', NULL, '2026-10-31 12:42:10.026', '2026-10-31 12:42:10.026', '0', '0');
INSERT INTO `FAQ` (`id`, `category`, `question`, `answer`, `order`, `status`, `publishedAt`, `createdAt`, `updatedAt`, `isPublished`, `displayOrder`) VALUES ('faq-7cc2e2c41b0ac22382e88453a8c44b19', 'GENERAL', 'How fast are digital service orders processed on HambakTech?', 'Telecom and VTU orders (airtime, SME data, exam tokens) are processed instantly via automated API gateways (< 30 seconds). Identity and NIN requests are verified and delivered within 5 to 30 minutes.', '0', 'DRAFT', NULL, '2026-10-08 03:13:06.712', '2026-10-08 03:13:06.712', '1', '1');
INSERT INTO `FAQ` (`id`, `category`, `question`, `answer`, `order`, `status`, `publishedAt`, `createdAt`, `updatedAt`, `isPublished`, `displayOrder`) VALUES ('faq-847421b4ac635c87b64fb50eab57d897', 'NIN', 'Is my personal and biometric identity data secure?', 'Yes. HambakTech adheres to strict NDPR and global data security guidelines with end-to-end encryption in transit and at rest. We do not store sensitive raw biometric fingerprints.', '0', 'DRAFT', NULL, '2026-10-08 03:13:06.841', '2026-10-08 03:13:06.841', '1', '3');
INSERT INTO `FAQ` (`id`, `category`, `question`, `answer`, `order`, `status`, `publishedAt`, `createdAt`, `updatedAt`, `isPublished`, `displayOrder`) VALUES ('faq-aa9a875a7bed9f9b6133516938f9b552', 'ACADEMY', 'Are HambakTech Academy certificates verifiable?', 'Yes, every certificate issued upon completing a HambakTech Academy course includes a unique cryptographic verification number and verifiable public URL.', '0', 'DRAFT', NULL, '2026-10-08 03:13:06.907', '2026-10-08 03:13:06.907', '1', '4');
INSERT INTO `FAQ` (`id`, `category`, `question`, `answer`, `order`, `status`, `publishedAt`, `createdAt`, `updatedAt`, `isPublished`, `displayOrder`) VALUES ('faq-c4ac0e5ca223a1bfaa0f506350920ea8', 'Services', 'How do I place an order for digital and technical services?', 'You can explore our Services Catalog, view detailed requirements and deliverables, and sign in to your customer account to place orders directly with transparent SLA timelines.', '0', 'DRAFT', NULL, '2026-10-07 01:15:04.937', '2026-10-07 01:15:04.937', '1', '1');

