DROP TABLE IF EXISTS `HomepageFeature`;
CREATE TABLE `HomepageFeature` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ShieldCheck',
  `displayOrder` int NOT NULL DEFAULT '0',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_feat_order` (`displayOrder`),
  KEY `idx_feat_active` (`isActive`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `HomepageFeature` (`id`, `title`, `description`, `icon`, `displayOrder`, `isActive`, `createdAt`, `updatedAt`) VALUES ('feat-1', 'Automated Instant VTU & Utility Settlement', 'Instant automated fulfillment for MTN, Airtel, Glo, 9mobile airtime and data, electricity DISCO tokens, and cable TV.', 'Zap', '1', '1', '2026-10-30 09:19:47.190', '2026-10-30 09:19:47.190');
INSERT INTO `HomepageFeature` (`id`, `title`, `description`, `icon`, `displayOrder`, `isActive`, `createdAt`, `updatedAt`) VALUES ('feat-2', 'Institutional NIN & Identity Verification', 'NIMC-compliant verification slips, tracking assistance, and identity rectification with strict NDPA 2023 data protection.', 'Fingerprint', '2', '1', '2026-10-30 09:19:47.190', '2026-10-30 09:19:47.190');
INSERT INTO `HomepageFeature` (`id`, `title`, `description`, `icon`, `displayOrder`, `isActive`, `createdAt`, `updatedAt`) VALUES ('feat-3', 'HambakTech Institute of Digital Innovations', '12 hands-on vocational courses in Software Engineering, UI/UX, Cybersecurity, Digital Marketing, and Data Analysis.', 'GraduationCap', '3', '1', '2026-10-30 09:19:47.190', '2026-10-30 09:19:47.190');
INSERT INTO `HomepageFeature` (`id`, `title`, `description`, `icon`, `displayOrder`, `isActive`, `createdAt`, `updatedAt`) VALUES ('feat-4', 'Moniepoint MFB Backed Escrow Wallet', 'Reliable ledger accounting with unique dedicated virtual accounts, real-time transaction reconciliation, and zero ledger leakage.', 'ShieldCheck', '4', '1', '2026-10-30 09:19:47.190', '2026-10-30 09:19:47.190');

