INSERT INTO `HomepageTestimonial` (`id`, `clientName`, `clientRole`, `content`, `rating`, `avatarUrl`, `displayOrder`, `isActive`, `createdAt`, `updatedAt`) VALUES ('test-1', 'Adebayo Ogunlesi', 'SME Business Owner', 'HambakTech processed our CAC corporate filing and business registration in record time. Professional support desk and transparent pricing.', '5', NULL, '1', '1', '2026-10-30 09:19:47.421', '2026-10-30 09:19:47.421');
INSERT INTO `HomepageTestimonial` (`id`, `clientName`, `clientRole`, `content`, `rating`, `avatarUrl`, `displayOrder`, `isActive`, `createdAt`, `updatedAt`) VALUES ('test-2', 'Fatima Aliyu', 'Software Engineering Graduate', 'The Academy practical curriculum gave me direct job-ready skills in React and Node.js. My student verification card was recognized immediately.', '5', NULL, '2', '1', '2026-10-30 09:19:47.421', '2026-10-30 09:19:47.421');
INSERT INTO `HomepageTestimonial` (`id`, `clientName`, `clientRole`, `content`, `rating`, `avatarUrl`, `displayOrder`, `isActive`, `createdAt`, `updatedAt`) VALUES ('test-3', 'Emeka Nwosu', 'Digital Agent & Partner', 'The automated VTU and bill payment turnaround is instant. My wallet funding via Moniepoint reflects in less than 5 seconds.', '5', NULL, '3', '1', '2026-10-30 09:19:47.421', '2026-10-30 09:19:47.421');

