DROP TABLE IF EXISTS `LegalDocument`;
CREATE TABLE `LegalDocument` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1.0',
  `status` enum('DRAFT','PUBLISHED','ARCHIVED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `effectiveDate` datetime(3) DEFAULT NULL,
  `publishedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `LegalDocument_slug_key` (`slug`),
  KEY `LegalDocument_status_idx` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `LegalDocument` (`id`, `slug`, `title`, `content`, `version`, `status`, `effectiveDate`, `publishedAt`, `createdAt`, `updatedAt`) VALUES ('leg-25d93cd25db7563101a586b59807dedf', 'refund', 'Refund & Cancellation Policy', 'Services that have not commenced processing may be cancelled by the client with funds automatically restored to their wallet balance. Services verified as completed with delivery proofs cannot be reversed.', '1.0.0', 'PUBLISHED', NULL, NULL, '2026-10-08 03:13:07.094', '2026-10-08 03:13:07.094');
INSERT INTO `LegalDocument` (`id`, `slug`, `title`, `content`, `version`, `status`, `effectiveDate`, `publishedAt`, `createdAt`, `updatedAt`) VALUES ('leg-7846d059f553e7fe90e5a2039d75f61f', 'cookies', 'Cookie & Tracking Policy', 'HambakTech utilizes strictly necessary first-party session cookies and security tokens to maintain encrypted user sessions and prevent CSRF attacks. No third-party ad tracking cookies are utilized.', '1.0.0', 'PUBLISHED', NULL, NULL, '2026-10-08 03:13:07.171', '2026-10-08 03:13:07.171');
INSERT INTO `LegalDocument` (`id`, `slug`, `title`, `content`, `version`, `status`, `effectiveDate`, `publishedAt`, `createdAt`, `updatedAt`) VALUES ('leg-b74bb5e2c5816d70a6c9a4a6115febac', 'terms', 'Terms of Service & Engagement', 'By registering, purchasing, or using services on the HambakTech platform, you agree to comply with these Terms of Service. All digital engineering, practical skills cohorts, and identity desk support are governed by their respective SLA delivery terms. Wallet balances are funded through authorized bank transfers and monitored under rigorous double-entry accounting.', '1.0.0', 'PUBLISHED', NULL, NULL, '2026-10-08 03:12:49.806', '2026-10-08 03:13:06.965');
INSERT INTO `LegalDocument` (`id`, `slug`, `title`, `content`, `version`, `status`, `effectiveDate`, `publishedAt`, `createdAt`, `updatedAt`) VALUES ('leg-bbdfdeb445e9eaeae8103248b6d94e3a', 'privacy', 'Privacy Policy & Data Protection', 'HambakTech complies strictly with the Nigeria Data Protection Regulation (NDPR) and international cybersecurity standards. We collect only necessary customer information to process orders and identify facilitation requests. Client records are encrypted server-side.', '1.0.0', 'PUBLISHED', NULL, NULL, '2026-10-08 03:13:07.025', '2026-10-08 03:13:07.025');

DROP TABLE IF EXISTS `LegalDocumentHistory`;
CREATE TABLE `LegalDocumentHistory` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `documentId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `changeSummary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `authorId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `LegalDocumentHistory_documentId_idx` (`documentId`),
  KEY `LegalDocumentHistory_version_idx` (`version`),
  CONSTRAINT `LegalDocumentHistory_documentId_fkey` FOREIGN KEY (`documentId`) REFERENCES `LegalDocument` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `MFAFactor`;
CREATE TABLE `MFAFactor` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `factorType` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `secretKey` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `isVerified` tinyint(1) NOT NULL DEFAULT '0',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `MFAFactor_userId_idx` (`userId`),
  CONSTRAINT `MFAFactor_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `MediaAsset`;
CREATE TABLE `MediaAsset` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fileName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `originalName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fileType` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mimeType` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fileSizeBytes` bigint NOT NULL,
  `url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GENERAL',
  `uploadedBy` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_media_category` (`category`),
  KEY `idx_media_created` (`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

