DROP TABLE IF EXISTS `NINRequestStatusHistory`;
CREATE TABLE `NINRequestStatusHistory` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `requestId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fromStatus` enum('DRAFT','SUBMITTED','PROCESSING','READY_FOR_PICKUP','DISPATCHED','COMPLETED','CANCELLED','REJECTED','UNDER_REVIEW','REQUEST_SUBMITTED','AWAITING_RESPONSE','UNVERIFIED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `toStatus` enum('DRAFT','SUBMITTED','PROCESSING','READY_FOR_PICKUP','DISPATCHED','COMPLETED','CANCELLED','REJECTED','UNDER_REVIEW','REQUEST_SUBMITTED','AWAITING_RESPONSE','UNVERIFIED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `changedBy` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comments` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `NINRequestStatusHistory_requestId_idx` (`requestId`),
  CONSTRAINT `NINRequestStatusHistory_requestId_fkey` FOREIGN KEY (`requestId`) REFERENCES `NINServiceRequest` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

