DROP TABLE IF EXISTS `NinSlipConfig`;
CREATE TABLE `NinSlipConfig` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `serviceCode` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `templateType` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'NIN',
  `description` text COLLATE utf8mb4_unicode_ci,
  `priceKobo` int NOT NULL,
  `providerCostKobo` int NOT NULL DEFAULT '10000',
  `isAvailable` tinyint(1) DEFAULT '1',
  `badge` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `previewImageUrl` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `displayOrder` int DEFAULT '0',
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `serviceCode` (`serviceCode`),
  KEY `NinSlipConfig_avail_cat_idx` (`isAvailable`,`category`,`displayOrder`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

