DROP TABLE IF EXISTS `NinSlipOrder`;
CREATE TABLE `NinSlipOrder` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slipConfigId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slipName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `templateType` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `identifierType` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `identifierValue` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amountPaidKobo` int NOT NULL,
  `paymentStatus` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'PAID',
  `verifiedDataJson` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reference` (`reference`),
  KEY `userId` (`userId`),
  KEY `NinSlipOrder_slipConfigId_fkey` (`slipConfigId`),
  CONSTRAINT `NinSlipOrder_slipConfigId_fkey` FOREIGN KEY (`slipConfigId`) REFERENCES `NinSlipConfig` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `NinSlipOrder_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

