DROP TABLE IF EXISTS `NotificationPreference`;
CREATE TABLE `NotificationPreference` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `orders` tinyint(1) NOT NULL DEFAULT '1',
  `payments` tinyint(1) NOT NULL DEFAULT '1',
  `wallet` tinyint(1) NOT NULL DEFAULT '1',
  `academy` tinyint(1) NOT NULL DEFAULT '1',
  `nin` tinyint(1) NOT NULL DEFAULT '1',
  `support` tinyint(1) NOT NULL DEFAULT '1',
  `security` tinyint(1) NOT NULL DEFAULT '1',
  `announcements` tinyint(1) NOT NULL DEFAULT '1',
  `inApp` tinyint(1) NOT NULL DEFAULT '1',
  `email` tinyint(1) NOT NULL DEFAULT '1',
  `sms` tinyint(1) NOT NULL DEFAULT '0',
  `whatsapp` tinyint(1) NOT NULL DEFAULT '0',
  `updatedAt` datetime(3) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `marketing` tinyint(1) NOT NULL DEFAULT '1',
  `channelInApp` tinyint(1) NOT NULL DEFAULT '1',
  `channelEmail` tinyint(1) NOT NULL DEFAULT '1',
  `channelSms` tinyint(1) NOT NULL DEFAULT '0',
  `channelWhatsapp` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `NotificationPreference_userId_key` (`userId`),
  CONSTRAINT `NotificationPreference_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

