DROP TABLE IF EXISTS `PlatformSettings`;
CREATE TABLE `PlatformSettings` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'singleton',
  `defaultCurrency` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NGN',
  `allowedCurrencies` json DEFAULT NULL,
  `maintenanceMode` tinyint(1) NOT NULL DEFAULT '0',
  `enableCustomerRegistration` tinyint(1) NOT NULL DEFAULT '1',
  `enableWalletTransactions` tinyint(1) NOT NULL DEFAULT '1',
  `enableAcademyAdmissions` tinyint(1) NOT NULL DEFAULT '1',
  `enableNINRequests` tinyint(1) NOT NULL DEFAULT '1',
  `updatedAt` datetime(3) NOT NULL,
  `activityRetentionDays` int NOT NULL DEFAULT '90',
  `sessionRetentionDays` int NOT NULL DEFAULT '30',
  `autoPurgeEnabled` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `PlatformSettings` (`id`, `defaultCurrency`, `allowedCurrencies`, `maintenanceMode`, `enableCustomerRegistration`, `enableWalletTransactions`, `enableAcademyAdmissions`, `enableNINRequests`, `updatedAt`, `activityRetentionDays`, `sessionRetentionDays`, `autoPurgeEnabled`) VALUES ('singleton', 'NGN', '[\"NGN\"]', '0', '1', '1', '1', '1', '2026-11-05 20:17:58.901', '90', '30', '1');

DROP TABLE IF EXISTS `Product`;
CREATE TABLE `Product` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `priceKobo` int NOT NULL,
  `compareAtPriceKobo` int DEFAULT NULL,
  `imageUrl` text COLLATE utf8mb4_unicode_ci,
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Accessories',
  `stock` int DEFAULT '10',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `Product` (`id`, `name`, `slug`, `description`, `priceKobo`, `compareAtPriceKobo`, `imageUrl`, `category`, `stock`, `status`, `createdAt`, `updatedAt`) VALUES ('prod-a4-copy-paper', 'Chamex Premium A4 Copier Paper 80gsm (Ream)', 'chamex-premium-a4-copier-paper', '500 sheets of ultra-bright white 80gsm multipurpose paper. Perfect for high-speed laser printing, photocopying, and official document submissions.', '520000', '600000', 'https://images.unsplash.com/photo-1586075010923-2dd4570fb338?w=800&auto=format&fit=crop&q=80', 'Office Supplies', '40', 'ACTIVE', '2026-10-11 17:17:59', '2026-10-11 17:17:59');
INSERT INTO `Product` (`id`, `name`, `slug`, `description`, `priceKobo`, `compareAtPriceKobo`, `imageUrl`, `category`, `stock`, `status`, `createdAt`, `updatedAt`) VALUES ('prod-cat6-ethernet-cable', 'High-Speed Cat6 Gigabit Ethernet Cable RJ45 5M', 'high-speed-cat6-gigabit-cable-5m', 'Factory molded gold-plated RJ45 connectors with snagless boot. Delivers bandwidth up to 250MHz and 1000Mbps Gigabit data transmission.', '250000', '350000', 'https://images.unsplash.com/photo-1544716278-e513176f20b5?w=800&auto=format&fit=crop&q=80', 'Networking', '30', 'ACTIVE', '2026-10-11 17:17:59', '2026-10-11 17:17:59');
INSERT INTO `Product` (`id`, `name`, `slug`, `description`, `priceKobo`, `compareAtPriceKobo`, `imageUrl`, `category`, `stock`, `status`, `createdAt`, `updatedAt`) VALUES ('prod-hdmi-vga-adapter', 'Full HD 1080P HDMI to VGA Cable Adapter with Audio', 'hdmi-to-vga-adapter-1080p', 'Gold-plated HDMI male to VGA female converter adapter with 3.5mm audio port for connecting modern laptops to projectors and monitors.', '300000', '400000', 'https://images.unsplash.com/photo-1544816155-12df9643f363?w=800&auto=format&fit=crop&q=80', 'Power & Cables', '20', 'ACTIVE', '2026-10-11 17:17:59', '2026-10-11 17:17:59');
INSERT INTO `Product` (`id`, `name`, `slug`, `description`, `priceKobo`, `compareAtPriceKobo`, `imageUrl`, `category`, `stock`, `status`, `createdAt`, `updatedAt`) VALUES ('prod-lamination-pouches', 'Glossy Thermal Laminating Pouches A4 (100 Pack)', 'glossy-thermal-laminating-pouches-a4', 'Heavy duty 125 micron thermal laminating pouches. Provides crystal clear, waterproof, tamper-proof protection for certificates, ID cards, and menus.', '650000', '750000', 'https://images.unsplash.com/photo-1589829545856-d10d557cf95f?w=800&auto=format&fit=crop&q=80', 'Office Supplies', '15', 'ACTIVE', '2026-10-11 17:17:59', '2026-10-11 17:17:59');
INSERT INTO `Product` (`id`, `name`, `slug`, `description`, `priceKobo`, `compareAtPriceKobo`, `imageUrl`, `category`, `stock`, `status`, `createdAt`, `updatedAt`) VALUES ('prod-surge-protector', 'Heavy-Duty 4-Way Surge Protector Extension with USB', 'heavy-duty-4-way-surge-protector', 'Safe power extension with 4 universal socket outlets, 2 high-speed USB charging ports, 2-meter pure copper cable, and overload circuit breaker.', '800000', '950000', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Power & Cables', '16', 'ACTIVE', '2026-10-11 17:17:59', '2026-10-11 17:17:59');
INSERT INTO `Product` (`id`, `name`, `slug`, `description`, `priceKobo`, `compareAtPriceKobo`, `imageUrl`, `category`, `stock`, `status`, `createdAt`, `updatedAt`) VALUES ('prod-universal-charger', 'Universal Laptop Power Adapter 90W Multi-Tip', 'universal-laptop-power-adapter-90w', 'Versatile AC laptop charger with 10 interchangeable connector tips compatible with HP, Dell, Lenovo, Toshiba, Asus, and Acer laptops.', '950000', '1200000', 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=800&auto=format&fit=crop&q=80', 'Power & Cables', '12', 'ACTIVE', '2026-10-11 17:17:59', '2026-10-11 17:17:59');
INSERT INTO `Product` (`id`, `name`, `slug`, `description`, `priceKobo`, `compareAtPriceKobo`, `imageUrl`, `category`, `stock`, `status`, `createdAt`, `updatedAt`) VALUES ('prod-usb-flash-64gb', 'SanDisk Ultra 64GB USB 3.0 Flash Drive', 'sandisk-ultra-64gb-usb', 'High-speed USB 3.0 transfer speeds up to 130MB/s. Compact, sleek design ideal for document backups, software installers, and academic materials.', '450000', '550000', 'https://images.unsplash.com/photo-1618410320928-25228d811631?w=800&auto=format&fit=crop&q=80', 'Storage & Media', '25', 'ACTIVE', '2026-10-11 17:17:59', '2026-10-11 17:17:59');
INSERT INTO `Product` (`id`, `name`, `slug`, `description`, `priceKobo`, `compareAtPriceKobo`, `imageUrl`, `category`, `stock`, `status`, `createdAt`, `updatedAt`) VALUES ('prod-wireless-mouse', 'Logitech Wireless Optical Mouse 2.4GHz', 'logitech-wireless-optical-mouse', 'Reliable wireless connectivity with nano receiver, smooth optical tracking, 12-month battery life, and comfortable contoured grip.', '380000', '450000', 'https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?w=800&auto=format&fit=crop&q=80', 'Computer Peripherals', '18', 'ACTIVE', '2026-10-11 17:17:59', '2026-10-11 17:17:59');

DROP TABLE IF EXISTS `ProductOrder`;
CREATE TABLE `ProductOrder` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `orderNumber` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `totalAmountKobo` int NOT NULL,
  `paymentMethod` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `paymentStatus` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'PAID',
  `fulfillmentStatus` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING',
  `shippingAddress` text COLLATE utf8mb4_unicode_ci,
  `customerPhone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerEmail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerName` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `itemsJson` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `orderNumber` (`orderNumber`),
  KEY `userId` (`userId`),
  CONSTRAINT `ProductOrder_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `ProductOrder` (`id`, `orderNumber`, `userId`, `totalAmountKobo`, `paymentMethod`, `paymentStatus`, `fulfillmentStatus`, `shippingAddress`, `customerPhone`, `customerEmail`, `customerName`, `itemsJson`, `createdAt`, `updatedAt`) VALUES ('ord-str-1625ee1440ae7ac7', 'HTS-63D90425', 'usr-64704391dd702934fd962bdef9670e33', '1040000', 'DIRECT_TRANSFER', 'PENDING', 'PENDING', 'HambakTech Tech Centre Pickup Desk', '08098765432', 'store_cust_1791791893@test.hambaktech.com.ng', 'Store Tester', '[{\"productId\":\"prod-a4-copy-paper\",\"name\":\"Chamex Premium A4 Copier Paper 80gsm (Ream)\",\"priceKobo\":520000,\"priceNaira\":5200,\"quantity\":2,\"subtotalKobo\":1040000,\"imageUrl\":\"https:\\/\\/images.unsplash.com\\/photo-1586075010923-2dd4570fb338?w=800&auto=format&fit=crop&q=80\"}]', '2026-10-12 07:58:13', '2026-10-12 07:58:13');

DROP TABLE IF EXISTS `PromotionalBanner`;
CREATE TABLE `PromotionalBanner` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subtitle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `imageUrl` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ctaText` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ctaLink` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `displayOrder` int NOT NULL DEFAULT '0',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `startDate` datetime DEFAULT NULL,
  `endDate` datetime DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_banner_order` (`displayOrder`),
  KEY `idx_banner_active` (`isActive`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ProviderPriceHistory`;
CREATE TABLE `ProviderPriceHistory` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerId` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerProductId` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `serviceCode` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `network` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `oldProviderCostKobo` bigint NOT NULL,
  `newProviderCostKobo` bigint NOT NULL,
  `oldCustomerPriceKobo` bigint DEFAULT NULL,
  `newCustomerPriceKobo` bigint DEFAULT NULL,
  `changeType` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PROVIDER_COST_CHANGED',
  `changedBy` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'PROVIDER_SYNC',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'REVIEW_REQUIRED',
  `notes` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pph_providerId` (`providerId`),
  KEY `idx_pph_providerProductId` (`providerProductId`),
  KEY `idx_pph_serviceCode` (`serviceCode`),
  KEY `idx_pph_status` (`status`),
  KEY `idx_pph_createdAt` (`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ProviderProduct`;
CREATE TABLE `ProviderProduct` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `serviceCode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerProductCode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `network` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dataSizeMb` int DEFAULT NULL,
  `validityDays` int DEFAULT NULL,
  `fulfillmentMode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AUTOMATED',
  `providerCostKobo` bigint NOT NULL DEFAULT '0',
  `previousProviderCostKobo` bigint NOT NULL DEFAULT '0',
  `priceChangedAt` datetime DEFAULT NULL,
  `priceChangeStatus` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NORMAL',
  `lastSyncAt` datetime DEFAULT NULL,
  `isAvailable` tinyint(1) NOT NULL DEFAULT '1',
  `metadataJson` json DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `ProviderProduct_providerId_idx` (`providerId`),
  KEY `ProviderProduct_serviceCode_idx` (`serviceCode`),
  KEY `ProviderProduct_fulfillmentMode_idx` (`fulfillmentMode`),
  KEY `idx_prod_price_change_status` (`priceChangeStatus`),
  CONSTRAINT `ProviderProduct_providerId_fkey` FOREIGN KEY (`providerId`) REFERENCES `IntegrationProvider` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

