DROP TABLE IF EXISTS `ProviderTransaction`;
CREATE TABLE `ProviderTransaction` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `orderItemId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `serviceCode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `clientReference` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerReference` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `costKobo` bigint NOT NULL DEFAULT '0',
  `amountKobo` bigint NOT NULL DEFAULT '0',
  `rawStatus` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requestPayload` json DEFAULT NULL,
  `responsePayload` json DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `orderId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `serviceId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profitKobo` bigint NOT NULL DEFAULT '0',
  `errorMessage` text COLLATE utf8mb4_unicode_ci,
  `resultData` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ProviderTransaction_clientReference_key` (`clientReference`),
  KEY `ProviderTransaction_providerId_idx` (`providerId`),
  KEY `ProviderTransaction_providerReference_idx` (`providerReference`),
  KEY `ProviderTransaction_status_idx` (`status`),
  KEY `ProviderTransaction_createdAt_idx` (`createdAt`),
  KEY `idx_pt_userid` (`userId`),
  CONSTRAINT `ProviderTransaction_providerId_fkey` FOREIGN KEY (`providerId`) REFERENCES `IntegrationProvider` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

