DROP TABLE IF EXISTS `ProviderWebhookConfig`;
CREATE TABLE `ProviderWebhookConfig` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `endpointPath` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `httpMethod` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'POST',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `authType` enum('NONE','API_KEY','BEARER','BASIC_AUTH','HMAC','CUSTOM_HEADER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HMAC',
  `secretEncrypted` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `headerName` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signatureHeader` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signatureAlgorithm` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SHA-256',
  `signatureFormat` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'hex',
  `timestampHeader` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `timestampToleranceSec` int NOT NULL DEFAULT '300',
  `ipAllowlist` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `eventTypesJson` json DEFAULT NULL,
  `retryPolicyJson` json DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `lastTriggeredAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_pwc_provider_endpoint` (`providerId`,`endpointPath`),
  KEY `idx_pwc_providerId` (`providerId`),
  KEY `idx_pwc_isActive` (`isActive`),
  CONSTRAINT `fk_pwc_providerId` FOREIGN KEY (`providerId`) REFERENCES `IntegrationProvider` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

