DROP TABLE IF EXISTS `SmtpConfig`;
CREATE TABLE `SmtpConfig` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `host` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mail.hambaktech.com.ng',
  `port` int NOT NULL DEFAULT '465',
  `encryption` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ssl',
  `username` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `passwordEncrypted` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `fromEmail` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'no-reply@hambaktech.com.ng',
  `fromName` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HambakTech',
  `replyToEmail` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `isVerified` tinyint(1) NOT NULL DEFAULT '0',
  `lastTestedAt` datetime(3) DEFAULT NULL,
  `lastTestStatus` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lastTestError` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `updatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `SmtpConfig` (`id`, `host`, `port`, `encryption`, `username`, `passwordEncrypted`, `fromEmail`, `fromName`, `replyToEmail`, `isActive`, `isVerified`, `lastTestedAt`, `lastTestStatus`, `lastTestError`, `updatedAt`, `createdAt`) VALUES ('default', 'lon110.truehost.cloud', '465', 'ssl', 'notifications@hambaktech.com.ng', 'M9zrFrHMiEkcvCb2Kf963zo6MHYybTYrVWJjdFIzNFVWVXZ1V3dkZz09', 'notifications@hambaktech.com.ng', 'HambakTech Services', 'support@hambaktech.com.ng', '1', '1', '2026-10-31 13:03:26.974', 'SUCCESS', NULL, '2026-10-31 13:03:26.974', '2026-10-31 12:40:14.432');

DROP TABLE IF EXISTS `Student`;
CREATE TABLE `Student` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentIdNumber` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `registrationNumber` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `registeredAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Student_userId_key` (`userId`),
  UNIQUE KEY `Student_studentIdNumber_key` (`studentIdNumber`),
  UNIQUE KEY `Student_registrationNumber_key` (`registrationNumber`),
  CONSTRAINT `Student_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `Student` (`id`, `userId`, `studentIdNumber`, `registrationNumber`, `status`, `registeredAt`, `updatedAt`) VALUES ('stu-edbb4b4eac960ff1cd4a92d4e14732c0', 'usr-2581daa91cc85efbe0256802c08b51ec', 'HAM-STU-2026-272FA', 'REG/2026/EFA4A', 'active', '2026-11-05 19:16:52.783', '2026-11-05 19:16:52.783');

DROP TABLE IF EXISTS `StudentCard`;
CREATE TABLE `StudentCard` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `cardNumber` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `StudentCard_studentId_fkey` (`studentId`),
  CONSTRAINT `StudentCard_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `Student` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `SupportMessage`;
CREATE TABLE `SupportMessage` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ticketId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `senderId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `attachments` json DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `senderRole` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
