DROP TABLE IF EXISTS `UserActivity`;
CREATE TABLE `UserActivity` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sessionId` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `activityType` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `action` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `route` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `method` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resourceType` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resourceId` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ipAddress` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `country` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `region` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `timezone` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deviceType` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `os` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `browser` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `browserVersion` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `userAgent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUCCESS',
  `responseStatus` int NOT NULL DEFAULT '200',
  `severity` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INFO',
  `correlationId` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `detailsJson` longtext COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_useractivity_user` (`userId`),
  KEY `idx_useractivity_type` (`activityType`),
  KEY `idx_useractivity_category` (`category`),
  KEY `idx_useractivity_created` (`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

