DROP TABLE IF EXISTS `bulk_sms_records`;
CREATE TABLE `bulk_sms_records` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sender_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `recipients_count` int NOT NULL,
  `recipients_sample` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `pages` int NOT NULL DEFAULT '1',
  `units_charged` decimal(10,2) NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `status` enum('DELIVERED','PENDING','FAILED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DELIVERED',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_bsms_user` (`user_id`),
  CONSTRAINT `fk_bsms_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

