DROP TABLE IF EXISTS `email_templates`;
CREATE TABLE `email_templates` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `template_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` enum('Auth','Wallet','Transactions','Services','Security','Admin') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Auth',
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `html_body` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `variables` json NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `template_key` (`template_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_acc_sec', 'account_security', 'Account Security Alert', 'Security', 'Security Alert: {{event_type}} on Your Account', 'Dear {{name}}, A security event ({{event_type}}) was logged from IP {{ip_address}}.', 'Instant fraud and security notice.', '[\"name\", \"event_type\", \"ip_address\", \"timestamp\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_adm_alert', 'admin_alert', 'Administrative System Alert', 'Admin', '[URGENT] System Event Alert: {{alert_title}}', 'Attention Administrator, {{alert_message}} occurred on HambakTech production server at {{timestamp}}.', 'Critical telemetry alert for administrators.', '[\"alert_title\", \"alert_message\", \"severity\", \"timestamp\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_email_verif', 'email_verification', 'Email Verification', 'Auth', 'Verify Your HambakTech Email Address', 'Dear {{name}}, Please verify your email using this code: {{code}}.', 'Used for 2FA or email activation.', '[\"name\", \"code\", \"expiry\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_pay_appr', 'payment_approval', 'Payment Approval Notice', 'Wallet', 'Your Manual Deposit of ₦{{amount}} Has Been Approved', 'Dear {{name}}, Your manual transfer deposit (Ref: {{reference}}) has been verified.', 'Sent when admin approves manual transfer.', '[\"name\", \"amount\", \"reference\", \"date\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_pay_rej', 'payment_rejection', 'Payment Rejection Notice', 'Wallet', 'Notice Concerning Your Manual Funding Request', 'Dear {{name}}, Your funding request for ₦{{amount}} was declined. Reason: {{reason}}.', 'Sent when admin rejects manual proof.', '[\"name\", \"amount\", \"reason\", \"reference\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_pw_reset', 'password_reset', 'Password Reset', 'Auth', 'HambakTech Password Reset Request', 'Dear {{name}}, Reset your account password by visiting: {{reset_url}}.', 'Security password reset token.', '[\"name\", \"reset_url\", \"expiry\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_reg', 'registration', 'Registration & Welcome', 'Auth', 'Welcome to HambakTech Enterprise - Your Account is Ready', 'Dear {{name}}, Welcome to HambakTech Enterprise Portal. Your registered email is {{email}}.', 'Sent immediately upon customer registration.', '[\"name\", \"email\", \"login_url\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_serv_res', 'service_results', 'Identity Service Result Slip', 'Services', 'Sovereign Verification Result: {{service_name}}', 'Dear {{name}}, Your NIMC/BVN verification request has concluded. Find your sovereign verification document attached.', 'Delivered with slip PDF.', '[\"name\", \"service_name\", \"nin\", \"slip_url\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_txn_fail', 'transaction_failed', 'Failed Transaction Notice', 'Transactions', 'Transaction Failed - Refund Processed', 'Dear {{name}}, Your request for {{service_name}} could not be fulfilled. ₦{{amount}} has been refunded.', 'Dispatched on provider error.', '[\"name\", \"service_name\", \"amount\", \"reason\", \"reference\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_txn_pend', 'transaction_pending', 'Pending Transaction Advisory', 'Transactions', 'Transaction Advisory: Order In Processing', 'Dear {{name}}, Your order for {{service_name}} (Ref: {{reference}}) is processing upstream.', 'Issued during provider queuing.', '[\"name\", \"service_name\", \"reference\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_txn_succ', 'transaction_success', 'Successful Transaction Receipt', 'Transactions', 'Receipt: {{service_name}} Completed Successfully', 'Dear {{name}}, Your purchase of {{service_name}} for ₦{{amount}} was delivered. Token/PIN: {{token_pin}}.', 'Delivered upon successful airtime, data, or verification.', '[\"name\", \"service_name\", \"amount\", \"token_pin\", \"reference\"]', '1', '2026-11-11 13:04:17');
INSERT INTO `email_templates` (`id`, `template_key`, `name`, `category`, `subject`, `html_body`, `description`, `variables`, `is_active`, `updated_at`) VALUES ('tpl_wallet_fund', 'wallet_funding', 'Wallet Funding Credit', 'Wallet', 'Wallet Credit Alert: ₦{{amount}} Received', 'Dear {{name}}, Your wallet has been credited with ₦{{amount}}. New Balance: ₦{{balance}}.', 'Instant receipt for wallet funding.', '[\"name\", \"amount\", \"balance\", \"reference\"]', '1', '2026-11-11 13:04:17');

