DROP TABLE IF EXISTS `telecom_orders`;
CREATE TABLE `telecom_orders` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `service_type` enum('data','airtime','airtime_pin','airtime_swap','cable','data_pin','bulksms','electricity','exam') COLLATE utf8mb4_unicode_ci NOT NULL,
  `network` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plan` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `cost_price` decimal(15,2) NOT NULL,
  `profit` decimal(15,2) NOT NULL DEFAULT '0.00',
  `provider_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider_ref` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('successful','pending','failed','refunded') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `metadata` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_to_user` (`user_id`),
  KEY `idx_to_status` (`status`),
  CONSTRAINT `fk_to_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
