DROP TABLE IF EXISTS `verification_records`;
CREATE TABLE `verification_records` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `service_key` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `search_value` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cost` decimal(15,2) NOT NULL,
  `provider_cost` decimal(15,2) DEFAULT NULL,
  `status` enum('completed','failed','pending') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `reference` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slip_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `has_slip` tinyint(1) NOT NULL DEFAULT '0',
  `result_data` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reference` (`reference`),
  KEY `idx_vr_user` (`user_id`),
  KEY `idx_vr_search` (`search_value`),
  CONSTRAINT `fk_vr_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `wallet_ledger`;
CREATE TABLE `wallet_ledger` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `wallet_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entry_type` enum('CREDIT','DEBIT') COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `balance_before` decimal(15,2) NOT NULL,
  `balance_after` decimal(15,2) NOT NULL,
  `reference` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reference` (`reference`),
  KEY `fk_ledger_wallet` (`wallet_id`),
  KEY `idx_ledger_user_created` (`user_id`,`created_at`),
  KEY `idx_ledger_ref` (`reference`),
  CONSTRAINT `fk_ledger_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_ledger_wallet` FOREIGN KEY (`wallet_id`) REFERENCES `wallets` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `wallet_ledger` (`id`, `wallet_id`, `user_id`, `entry_type`, `amount`, `balance_before`, `balance_after`, `reference`, `category`, `description`, `created_at`) VALUES ('01c52631-d068-433d-8e4f-f400ec6e8aa3', 'wal_94860c07f7abcba23b28', 'usr-38363e6cf63444b63b83309fa484114a', 'CREDIT', '98.00', '1304.00', '1402.00', 'REFUND_UD_PIN_AE0D8FC6DF85', 'manual_adjustment', 'Refund for failed PIN order UD_PIN_AE0D8FC6DF85', '2026-11-10 19:27:07');
